<script>
// --- dogmazic perf patch: load UberViz after the page is idle, off the critical path ---
// Scripts keep their original order; ShowVisualizer()/ShowEqualizer() are unchanged and
// simply work once these have loaded (which happens shortly after first paint).
(function () {
    var _uvFiles = [
        "<?php echo $web_path; ?>/lib/modules/UberViz/minivents.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/Detector.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/three.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/stats.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/dat.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/SimplexNoise.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/AdditiveBlendShader.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/BadTVShader.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/ATUTil.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/EffectComposer.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/RenderPass.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/ShaderPass.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/MaskPass.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/BloomPass.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/CopyShader.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/ConvolutionShader.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/HorizontalBlurShader.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/VerticalBlurShader.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/MirrorShader.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/RGBShiftShader.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/FilmShader.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/Main.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/AudioHandler.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/ControlsHandler.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/FXHandler.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/VizHandler.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/Bars.js",
        "<?php echo $web_path; ?>/lib/modules/UberViz/WhiteRing.js"
    ];
    function _loadUberViz() {
        (function next(i) {
            if (i >= _uvFiles.length) { return; }
            var s = document.createElement("script");
            s.src = _uvFiles[i];
            s.onload = function () { next(i + 1); };
            s.onerror = function () { next(i + 1); };
            document.body.appendChild(s);
        })(0);
    }
    if ("requestIdleCallback" in window) {
        window.addEventListener("load", function () { requestIdleCallback(_loadUberViz); });
    } else {
        window.addEventListener("load", function () { setTimeout(_loadUberViz, 1200); });
    }
})();
</script>
